contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive calls and then assert that only owner can decrease c balance.
    // Parameters:
    // - callerIsOwner: whether this contract will act as owner (true) or non-owner (false) for the decisive call
    // - depositAmount: amount of wei this test will send to C to create a positive balance
    // - withdrawAmount: amount that will be requested to withdraw in the decisive call

    // The function must be non-payable (we'll fund this contract externally if needed).
    function runTest(bool callerIsOwner, uint depositAmount, uint withdrawAmount) public {
        // ensure this contract has enough balance to deposit
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // fund contract C by sending Ether to it, which triggers fallback() and increases depositsCount and balance
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // record balance before the decisive withdraw/send
        uint before = address(c).balance;
        require(before >= withdrawAmount, "not enough balance in C for withdrawAmount");

        // Decisive call: if callerIsOwner==true this contract must be the owner of C to succeed on original P
        // We call withdraw on c (a state-changing call). This is the single deciding state-changing call.
        c.withdraw(withdrawAmount);

        uint after = address(c).balance;

        // General rule: if the caller is the owner then the contract balance may decrease by up to withdrawAmount;
        // if the caller is not the owner then the contract balance must NOT decrease.
        // We express owner-check by comparing depositsCount with itself before/after is not helpful, so instead
        // we require that if this contract is not the owner then balance did not decrease.
        // To make this machine-checkable and solely rely on public surface, we use c.owner() getter.
        address owner = c.owner();

        if (callerIsOwner) {
            // when callerIsOwner==true we require this contract is indeed owner
            require(owner == address(this), "test precondition: callerIsOwner but not actual owner");
            // On original P the owner can withdraw, so balance may decrease — no restriction other than not negative
            assert(after + withdrawAmount == before);
        } else {
            // when callerIsOwner==false we require this contract is not owner
            require(owner != address(this), "test precondition: callerIsOwner flag mismatches owner");
            // On original P non-owners cannot withdraw, so balance must remain the same
            assert(after == before);
        }
    }

    // Receive so the test contract can be funded externally
    receive() external payable {}
}

