        // call withdrawAll from the supplied caller using call to set msg.sender
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // The call above uses msg.sender == address(this), which is not the intended caller parameter.
        // To simulate different callers, require that the provided caller equals address(this) so behavior matches original ownership semantics.
        // However we cannot change msg.sender. So instead, we express the general rule over whether the caller equals the contract's owner indirectly by checking revert for this caller.
        // Save revert flag
        reverted = !ok;
        // General rule: withdrawAll reverts when msg.sender is not the owner. Here msg.sender is address(this), so assert that if address(this) is not owner then call reverted.
