import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: a non-owner caller and an amount to attempt a sendMoney that could change contract balance
    function testFuzz_property(address caller, uint256 value) public {
        // 1) Make caller distinct from the contract deployer (owner). The reference behavior we assert
        //    concerns non-owners; constrain to non-zero and non-owner addresses.
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        // ensure caller != owner (owner is the address that deployed c in setUp(), which is this contract)
        vm.assume(caller != address(this));

        // 2) Fund the contract so it has balance to potentially be sent out
        uint256 seedBalance = bound(value, 1, 1 ether); // keep value wide but non-zero; seedBalance used to fund c
        vm.deal(address(this), 2 ether);
        // deposit ether into c by calling fallback: send plain transfer from this (owner)
        // Owner's fallback increments depositsCount and provides contract balance
        (bool okSend,) = address(c).call{value: seedBalance}("");
        require(okSend, "owner funding failed");

        uint256 before = address(c).balance;

        // 3) Now have the FUZZED caller try to invoke sendMoney on c; because low-level call to EOAs never revert,
        //    and behavior difference arises from whether the non-owner is allowed to trigger outgoing call,
        //    we must simulate caller as an EOA here (fuzzer supplies address) and perform vm.prank to call.
        //    The reference requires that non-owner caller cannot trigger outgoing transfers — thus contract balance
        //    must remain identical after the call for ALL admissible inputs. The mutant inverts onlyOwner and
        //    will allow some non-owner calls to cause outgoing transfer and change the balance for some inputs.

        vm.prank(caller);
        // call sendMoney with an arbitrary target (use caller as target) and the fuzzed value bounded to contract balance
        uint256 sendVal = bound(value, 0, before);
        // perform the call; non-owner in reference should not be allowed to cause outgoing transfer,
        // but since sendMoney is public and guarded by onlyOwner, the call will simply revert in reference when
        // caller != owner; however, the fallback of the reference contract does not revert on send, so to
        // observe a consistent universal property across all fuzz inputs we observe whether the call succeeded
        // and that the contract balance remains unchanged.
        bool success;
        try c.sendMoney{value: 0}(address(caller), sendVal) {
            success = true;
        } catch {
            success = false;
        }

        uint256 after = address(c).balance;

        // GENERAL ASSERTION: For every non-owner caller and any sendVal, the reference contract ensures the contract's balance does not decrease as a result of caller invoking sendMoney; i.e., address(c).balance >= before.
        // This holds for the reference on all admissible inputs; the mutant (which inverts onlyOwner) allows some non-owner calls to trigger outgoing transfer and thus make after < before for some fuzz inputs.
        assertTrue(after >= before);
    }
}

